const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const targetRunId = typeof $json.runId === 'string' ? $json.runId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const safeRunId = /^[A-Za-z0-9._:-]{1,120}$/;
const ALLOWED = ['all', 'ready', 'uncertain', 'accepted', 'executed'];
const raw = typeof $json.filter === 'string' ? $json.filter.trim().toLowerCase() : '';
const filter = ALLOWED.includes(raw) ? raw : 'all';
const rawCursor=String($json.cursor??'').trim(),rawLimit=String($json.limit??'').trim();
const cursor=rawCursor===''?0:(/^\d+$/.test(rawCursor)?Number(rawCursor):NaN);
const limit=rawLimit===''?20:(/^\d+$/.test(rawLimit)?Number(rawLimit):NaN);
let error=null;
if(!uuidPattern.test(sessionId)||!uuidPattern.test(requestId))error={code:'INVALID_SESSION',message:'Reading the suggestions needs a valid conversation and request ID.'};
else if(targetRunId&&!safeRunId.test(targetRunId))error={code:'INVALID_RUN_ID',message:'The requested review run ID is invalid.'};
else if(!Number.isSafeInteger(cursor)||cursor<0||cursor>5000)error={code:'INVALID_CURSOR',message:'The suggestion cursor must be an integer from 0 to 5000.'};
else if(!Number.isSafeInteger(limit)||limit<1||limit>50)error={code:'INVALID_LIMIT',message:'The suggestion page size must be an integer from 1 to 50.'};
return [{ json: {
  valid: error === null, sessionId, requestId, targetRunId, filter, cursor, limit,
  proposedInput: { sessionId, requestId, runId:targetRunId, filter, cursor:String(cursor), limit:String(limit) },
  ...(error ? { response: { ok: false, error } } : {}),
} }];

const input = $('Validate Read Input').first().json;
const sessionRows = $input.all().map((item) => item.json).filter((row) => row && row.runId && String(row.sessionId ?? '') === input.sessionId);
const rows = input.targetRunId ? sessionRows.filter((row) => String(row.runId) === input.targetRunId) : sessionRows;

const minutesSince = (value) => {
  const parsed = Date.parse(String(value ?? ''));
  if (Number.isNaN(parsed)) return null;
  return Math.round((Date.now() - parsed) / 60000);
};
// Same number as the guard in 102: past the run workflow's own timeout, n8n
// has certainly stopped it, so a row still saying 'running' is wreckage.
const DEAD_AFTER = 31;

const finished = rows.filter((row) => ['completed', 'partial'].includes(String(row.status ?? '')));
const running = rows.filter((row) => String(row.status ?? '') === 'running')
  .map((row) => ({ ...row, age: minutesSince(row.startedAt) }))
  .filter((row) => row.age !== null);

const live = running.find((row) => row.age < DEAD_AFTER) ?? null;
const wreck = running.find((row) => row.age >= DEAD_AFTER) ?? null;
const latest = finished[0] ?? null;

return [{ json: { ...input,
  runId: latest ? String(latest.runId) : input.targetRunId,
  hasRun: latest !== null,
  targeted: Boolean(input.targetRunId),
  targetMissing: Boolean(input.targetRunId && rows.length === 0),
  running: live !== null,
  runningMinutes: live ? live.age : 0,
  interrupted: latest === null && wreck !== null,
  interruptedMinutes: wreck ? wreck.age : 0,
  run: latest ?? null } }];

const picked=$('Pick Run').first().json;
const rows=$input.all().map((item)=>item.json).filter((row)=>row&&row.suggestionId&&String(row.sessionId??'')===picked.sessionId&&String(row.runId??'')===picked.runId),cursor=Number.isSafeInteger(picked.cursor)?picked.cursor:0,limit=Number.isSafeInteger(picked.limit)?picked.limit:20;
if(!picked.hasRun){const message=picked.running?`The requested review has been running for ${picked.runningMinutes} minute${picked.runningMinutes===1?'':'s'} and has not finished yet.`:picked.interrupted?`The requested review started ${picked.interruptedMinutes} minutes ago and never finished. Offer to run another one.`:picked.targetMissing?`Review ${picked.targetRunId} does not exist in this conversation. Do not substitute a newer or older review.`:picked.targeted?'The requested review did not finish successfully. Do not substitute another review.':'No review has finished yet. Offer to capture a fresh user-mediated Xero Uncoded Statement Lines export and run one rather than guessing.';return [{json:{...picked,response:{ok:true,hasRun:false,requestedRunId:picked.targetRunId||'',running:picked.running,interrupted:picked.interrupted,suggestions:[],pagination:{cursor:0,limit,totalReturned:0,pageReturned:0,remaining:0,hasMore:false,nextCursor:null},message}}}];}
const money=(row)=>{const value=Number(row.amount??0);return `${value<0?'-':''}$${Math.abs(value).toFixed(2)}`;};
const who=(row)=>String(row.contactName||row.suggestedContact||row.narration||row.description||'unnamed').slice(0,60);
const render=(row)=>({suggestionId:String(row.suggestionId),statementLineId:String(row.statementLineId||''),line:`${String(row.occurredAt??'').slice(0,10)}  ${money(row)}  ${who(row)}`,date:String(row.occurredAt??'').slice(0,10),amount:money(row),counterparty:who(row),likelyDescription:String(row.likelyDescription||''),evidenceSummary:String(row.evidenceSummary||''),reviewQuestion:String(row.reviewQuestion||''),account:String(row.suggestedAccountCode||'')&&`${row.suggestedAccountCode} ${row.suggestedAccountName}`.trim(),taxType:String(row.suggestedTaxType||''),contactId:String(row.suggestedContactId||''),invoice:String(row.matchedInvoiceNumber||''),basis:String(row.basis||''),resultLane:String(row.resultLane||''),readyInXero:String(row.readyInXero)==='yes',confidence:Number(row.confidence||0),executionStatus:String(row.executionStatus||'')});
const stable=(a,b)=>String(a.occurredAt||'').localeCompare(String(b.occurredAt||''))||String(a.suggestionId||'').localeCompare(String(b.suggestionId||''));
const executed=rows.filter((row)=>String(row.readyInXero)==='yes'||String(row.executionStatus)==='created').sort(stable);
const executedIds=new Set(executed.map((row)=>row.suggestionId));
const accepted=rows.filter((row)=>!executedIds.has(row.suggestionId)&&String(row.userDecision)==='accepted').sort(stable);
const decidedIds=new Set([...executed,...accepted,...rows.filter((row)=>String(row.userDecision||''))].map((row)=>row.suggestionId));
const pending=rows.filter((row)=>!decidedIds.has(row.suggestionId));
const ready=pending.filter((row)=>String(row.resultLane)==='ready_to_prepare').sort(stable);
const matchInXero=pending.filter((row)=>String(row.resultLane)==='existing_match').sort(stable);
const needsYou=pending.filter((row)=>String(row.resultLane)==='likely').sort(stable);
const blocked=pending.filter((row)=>String(row.resultLane)==='blocked').sort(stable);
const lanes={ready,matchInXero,needsYou,blocked,accepted,executed};
const order={all:['needsYou','blocked','ready','matchInXero','accepted','executed'],uncertain:['needsYou','blocked'],ready:['ready'],accepted:['accepted'],executed:['executed']}[picked.filter];
const interleave=(names)=>{const result=[];const longest=Math.max(0,...names.map((lane)=>lanes[lane].length));for(let index=0;index<longest;index+=1)for(const lane of names)if(lanes[lane][index])result.push({lane,row:lanes[lane][index]});return result;};
const ordered=picked.filter==='all'?interleave(order):order.flatMap((lane)=>lanes[lane].map((row)=>({lane,row})));
const page=ordered.slice(cursor,cursor+limit),next=cursor+page.length,hasMore=next<ordered.length;
const paged={ready:[],matchInXero:[],needsYou:[],blocked:[],accepted:[],executed:[]};for(const item of page)paged[item.lane].push(render(item.row));
const counts={total:rows.length,readyToApprove:ready.length,matchInXero:matchInXero.length,needsYou:needsYou.length,blocked:blocked.length,accepted:accepted.length,readyInXero:executed.length};
const consumed={ready:0,matchInXero:0,needsYou:0,blocked:0,accepted:0,executed:0};for(const item of ordered.slice(0,next))consumed[item.lane]+=1;
const remainingByLane={needsYou:needsYou.length-consumed.needsYou,blocked:blocked.length-consumed.blocked,readyToApprove:ready.length-consumed.ready,matchInXero:matchInXero.length-consumed.matchInXero,accepted:accepted.length-consumed.accepted,readyInXero:executed.length-consumed.executed};
const completeSummary=`Review ${picked.runId}: ${counts.needsYou} need your help, ${counts.blocked} are blocked, ${counts.readyToApprove} are ready for approval, ${counts.matchInXero} have a possible Xero match, ${counts.accepted} are already accepted, and ${counts.readyInXero} are already prepared in Xero.`;
const summary=`${completeSummary} Showing ${page.length} of ${ordered.length} detail rows for filter ${picked.filter}${hasMore?`; ${ordered.length-next} remain at cursor ${next}`:''}.`;
return [{json:{...picked,response:{ok:true,hasRun:true,runId:picked.runId,status:String(picked.run?.status||''),reportText:rows.length<=limit?String(picked.run?.reportText||summary):summary,completeSummary,counts,pagination:{cursor,limit,totalReturned:ordered.length,pageReturned:page.length,remaining:ordered.length-next,remainingByLane,hasMore,nextCursor:hasMore?String(next):null},readyToApprove:paged.ready,matchInXero:paged.matchInXero,needsYou:paged.needsYou,blocked:paged.blocked,alreadyAccepted:paged.accepted,readyInXero:paged.executed,errorSummary:String(picked.run?.errorSummary||''),nextStep:'The counts are complete for this exact saved review. For filter all, this page is deterministically interleaved so every non-empty lane is surfaced early, with needsYou and blocked first in each round. Present only the detail rows returned. If hasMore is true, state the exact remaining count and nextCursor; fetch bounded additional pages only when the current request needs those details, and never imply omitted details were shown. Lower-certainty rows include a likelyDescription and one reviewQuestion. Get explicit approval for exact readyToApprove items before preparation. Nothing is reconciled until the user completes Match or Find & Match and clicks OK in Xero.'}}}];

const input = $('Validate Read Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'get_reconciliation_suggestions',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').first().json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
